import numpy as np

def gram_schmidt(V):
    V = np.array(V, dtype=float)
    n, k = V.shape
    if np.linalg.matrix_rank(V) < k:
        raise ValueError("the columns are dependent")
    Q = np.zeros((n, k))
    for j in range(k):
        f = V[:, j].copy()
        for i in range(j):
            f -= (V[:, j] @ Q[:, i]) * Q[:, i]
        Q[:, j] = f / np.linalg.norm(f)
    return (np.round(Q, 6) + 0.0).tolist()
